import { useState, useEffect } from 'react';
import { useAppContext } from './context';
import c from 'classnames';

export default function SettingsModal() {
  const { user, setUser, setShowSettings } = useAppContext();
  const [name, setName] = useState('');
  const [key, setKey] = useState('');
  const [error, setError] = useState('');

  useEffect(() => {
    if (user) {
      setName(user.name);
      setKey(user.apiKey);
    }
  }, [user]);

  const handleSave = () => {
    if (!name.trim() || !key.trim()) {
      setError('Please fill in all fields.');
      return;
    }
    setUser({ name: name.trim(), apiKey: key.trim() });
    setShowSettings(false);
  };

  const handleClose = () => {
    setShowSettings(false);
    setError('');
  };

  return (
    <div className="modalOverlay" onClick={handleClose}>
      <div className="modalContent" onClick={(e) => e.stopPropagation()}>
        <div className="modalHeader">
          <h2>Settings</h2>
          <button className="closeButton" onClick={handleClose}>
            <span className="icon">close</span>
          </button>
        </div>

        <div className="inputGroup">
           <label>Your Name</label>
           <input 
             value={name} 
             onChange={e => setName(e.target.value)} 
             placeholder="Enter your name"
           />
        </div>

        <div className="inputGroup">
           <label>Gemini API Key</label>
           <input 
             type="password" 
             value={key} 
             onChange={e => setKey(e.target.value)} 
             placeholder="Enter API Key"
           />
           <p className="helper">
             Get a key from <a href="https://aistudio.google.com/app/apikey" target="_blank" rel="noreferrer">Google AI Studio</a>
           </p>
        </div>

        {error && <div className="errorBanner">{error}</div>}

        <div className="modalActions">
          <button className="button secondary" onClick={handleClose}>Cancel</button>
          <button className="button primary" onClick={handleSave}>Save Changes</button>
        </div>
      </div>
    </div>
  );
}

