  padding-left: 15px;
  background: var(--highlight);
  padding: 15px;
  border-radius: var(--radius);
  box-shadow: 2px 2px 0 var(--shadow-color);
}

.modeTable table {
  width: 100%;
  border-collapse: separate;
  border-spacing: 0;
  border: var(--border-width) solid var(--border);
  border-radius: var(--radius);
  overflow: hidden;
  box-shadow: 3px 3px 0 var(--shadow-color);
  background: var(--highlight);
}
.modeTable th {
  text-align: left;
  background: var(--background);
  color: var(--text);
  font-family: var(--font-header);
  font-size: 12px;
  padding: 15px;
  border-bottom: var(--border-width) solid var(--border);
  border-right: 1px solid var(--track);
}
.modeTable th:last-child {
    border-right: none;
}
.modeTable td {
  padding: 15px;
  border-bottom: 1px solid var(--track);
  border-right: 1px solid var(--track);
}
.modeTable td:last-child {
    border-right: none;
}
.modeTable tr:last-child td {
    border-bottom: none;
}
.modeTable tr.activeRow td {
  background-color: var(--active-item-bg);
}

.loading {
  display: flex;
  align-items: center;
  gap: 20px;
  font-family: var(--font-body);
  font-size: 20px;
  padding: 30px;
  background: var(--highlight);
  border: var(--border-width) solid var(--border);
  border-radius: var(--radius);
  box-shadow: 4px 4px 0 var(--shadow-color);
  justify-content: center;
}

/* Spinner - Less glitchy, more smooth retro */
.spinner {
  width: 24px;
  height: 24px;
  border: 4px solid var(--track);
  border-top-color: var(--primary);
  border-radius: 50%;
  animation: spin 1s linear infinite;
}
@keyframes spin {
  to { transform: rotate(360deg); }
}

.cancelButton {
  border: var(--border-width) solid var(--border);
  padding: 6px 12px;
  border-radius: var(--radius);
  background: var(--surface);
  color: var(--text);
  font-size: 16px;
}
.cancelButton:hover {
    background: var(--background);
}

.lineChart {
  width: 100%;
  height: 100%;
  min-height: 300px;
  border: var(--border-width) solid var(--border);
  background: var(--highlight);
  box-shadow: 4px 4px 0 var(--shadow-color);
  border-radius: var(--radius);
  padding: 10px;
}
.lineChart path {
  fill: none;
  stroke: var(--primary);
  stroke-width: 3px; 
  stroke-linecap: round; 
  stroke-linejoin: round;
}
.lineChart circle {
  fill: var(--surface);
  stroke: var(--secondary);
  stroke-width: 2px;
}

.axisLabels text {
  text-anchor: middle;
  font-size: 16px;
  fill: var(--text);
  font-family: var(--font-body);
}

.axisTitle {
  font-size: 14px;
  fill: var(--text);
  font-family: var(--font-header);
}

.dataPoint text {
  fill: var(--text);
  font-size: 14px;
  text-anchor: middle;
  font-family: var(--font-body);
}

.timeLabels text {
  cursor: pointer;
  fill: var(--link);
  text-decoration: none;
  font-weight: bold;
}
.timeLabels text:hover {
    fill: var(--secondary);
    text-decoration: underline;
}

video {
  width: 100%;
  height: 100%;
  max-height: calc(50vh - 54px);
  margin: 0 auto;
}

.videoPlayer {
  flex: 1;
  background: #111;
  display: flex;
  align-items: stretch;
  flex-direction: column;
  justify-content: center;
  font-size: 0;
  position: relative;
  user-select: none;
  border-left: var(--border-width) solid var(--border);

  /* Modern Monitor Look - Cleaner than CRT */
  border: 4px solid #222;
  border-radius: 8px;
  box-shadow: 0 4px 10px rgba(0,0,0,0.3);
}

.videoPlayer:fullscreen {
  max-height: 100vh;
  border: none;
  border-radius: 0;
}


.videoPlayer:has(.timecodeMarker:hover) .videoCaption {
  opacity: 0;
}
.mediaContainer {
  display: flex;
  flex: 1;
  position: relative;
  min-height: 200px;
  overflow: hidden;
  border-radius: 4px 4px 0 0;
}

.audioPlaceholder {
  position: absolute;
  inset: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  z-index: 1;
  pointer-events: none;
  background: radial-gradient(circle, #333 0%, #111 100%);
