import { useState, KeyboardEvent } from 'react';
import { useAppContext } from './context';
import c from 'classnames';

export default function LoginPage() {
  const { setUser } = useAppContext();
  const [name, setName] = useState('');
  const [key, setKey] = useState('');
  const [error, setError] = useState('');

  const handleLogin = () => {
    if (!name.trim() || !key.trim()) {
      setError('Please fill in all fields.');
      return;
    }
    setUser({ name: name.trim(), apiKey: key.trim() });
  };

  const handleKeyDown = (e: KeyboardEvent) => {
    if (e.key === 'Enter') {
      handleLogin();
    }
  };

  return (
    <div className="loginPage">
      <div className="loginCard">
        <div className="loginHeader">
          <span className="icon">smart_display</span>
          <h1>VIDEO ANALYZER</h1>
        </div>

        <p className="loginDescription">
          Unlock AI-powered video analysis. Enter your details to get started.
        </p>

        <div className="inputGroup">
           <label>Your Name</label>
           <input 
             value={name} 
             onChange={e => setName(e.target.value)} 
             placeholder="Enter your name"
             onKeyDown={handleKeyDown}
           />
        </div>

        <div className="inputGroup">
           <label>Gemini API Key</label>
           <input 
             type="password" 
             value={key} 
             onChange={e => setKey(e.target.value)} 
             placeholder="Enter API Key"
             onKeyDown={handleKeyDown}
           />
           <p className="helper">
             Don't have a key? <a href="https://aistudio.google.com/app/apikey" target="_blank" rel="noreferrer">Get one here</a>
           </p>
        </div>

        {error && <div className="errorBanner">{error}</div>}

        <button className="loginButton" onClick={handleLogin}>
          START SYSTEM <span className="icon">arrow_forward</span>
        </button>
      </div>
    </div>
  );
}

@charset "UTF-8";

/* RETRO PALETTE - REFINED */
.light {
  --background: #F0F2F5; /* Softer Gray */
  --surface: #FFFFFF;
  --text: #1A1A1A;
  --border: #2D2D2D;
  --highlight: #FFFFFF;
  --primary: #5C6BC0; /* Retro Blue */
  --secondary: #FF7043; /* Retro Orange */
  --accent: #66BB6A; /* Retro Green */
  --track: #BDBDBD;
  --link: #1565C0;
  --tooltip-bg: #2D2D2D;
  --tooltip-text: #FFFFFF;
  --active-item-bg: #E8EAF6;
  --shadow-color: rgba(0, 0, 0, 0.2);
}

.dark {
  --background: #121212; /* Deep Dark */
  --surface: #1E1E1E;
  --text: #E0E0E0;
  --border: #4A4A4A;
  --highlight: #2C2C2C;
  --primary: #7986CB;
  --secondary: #FF8A65;
  --accent: #81C784;
  --track: #424242;
  --link: #64B5F6;
  --tooltip-bg: #E0E0E0;
  --tooltip-text: #121212;
  --active-item-bg: #283593;
  --shadow-color: rgba(0, 0, 0, 0.5);
}

* {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
  font-variant-ligatures: none;
}

:root {
  --track-fill: #fff;
  --mid: #757575;
  /* Retro Fonts */
  --font-body: "VT323", monospace;
  --font-header: "Press Start 2P", cursive;

  /* Modern Retro Constants */
  --radius: 6px; /* Softens the blockiness */
  --border-width: 2px; /* Lighter borders */
}

html, body {
  height: 100%;
  font-family: var(--font-body);
  font-size: 18px; 
  background-color: var(--background);
  color: var(--text);
}

#root {
  width: 100%;
  height: 100%;
}

h1, h2, h3, h4, h5, h6 {
  font-family: var(--font-header);
  font-weight: normal;
  text-transform: uppercase;
  letter-spacing: 0px;
  line-height: 1.4;
  font-size: 14px; /* Reduced for better sizing */
}

li {
  list-style: none;
}

/* MODERN RETRO INPUTS */
input, textarea {
  font-family: var(--font-body);
  background: var(--surface);
  color: var(--text);
  border: var(--border-width) solid var(--border);
  outline: none;
  font-size: 20px;
  resize: none;
  user-select: text;
  border-radius: var(--radius);
  box-shadow: 2px 2px 0px 0px var(--shadow-color);
  transition: all 0.15s ease;
}

input::placeholder, textarea::placeholder {
  user-select: none;
  opacity: 0.5;
}

textarea {
  width: 100%;
  background: var(--highlight);
  padding: 12px;
  margin-bottom: 15px;
}

textarea:focus, input:focus {
  border-color: var(--primary);
  box-shadow: 3px 3px 0px 0px var(--shadow-color);
}

[role=button] {
  cursor: pointer;
}

/* MODERN RETRO BUTTONS */
button {
  font-family: var(--font-body); /* Switch to body font for cleaner UI */
  font-size: 20px; /* Readable size */
  text-transform: uppercase;
  letter-spacing: 0.5px;
  background: var(--surface);
  color: var(--text);
  border: var(--border-width) solid var(--border);
  cursor: pointer;
  user-select: none;
  display: flex;
  align-items: center;
  gap: 8px;
  border-radius: var(--radius);
  box-shadow: 2px 2px 0px 0px var(--shadow-color);
  transition: all 0.1s;
  padding: 6px 12px;
}

button:hover:not([disabled]) {
  transform: translateY(-1px);
  box-shadow: 3px 3px 0px 0px var(--shadow-color);
  background: var(--highlight);
}

button:active:not([disabled]) {
  transform: translateY(1px);
  box-shadow: 1px 1px 0px 0px var(--shadow-color);
}

button:disabled {
  opacity: 0.6;
  cursor: not-allowed;
  box-shadow: none;
  background: var(--track);
  border-color: transparent;
}

button .icon {
  display: block;
}

.button {
  padding: 10px 14px;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
}
.button.inactive {
  opacity: 0.3;
  pointer-events: none;
}
.button.primary {
  background: var(--primary);
  color: #FFF;
}
.button.primary:hover {
  background: var(--active-item-bg);
  color: var(--text);
}
.button.secondary {
