  flex-direction: column;
  gap: 20px;
  background-color: var(--surface);
  /* Subtle dot pattern for texture */
  background-image: radial-gradient(var(--track) 1px, transparent 1px);
  background-size: 20px 20px;
}
.output:hover .sentence {
  opacity: 0.7;
}
.output time {
  color: var(--link);
  padding: 2px 6px;
  border-radius: 4px;
  font-size: 0.9em;
  text-decoration: none;
  background: rgba(0,0,0,0.05);
  font-family: var(--font-body);
  border: 1px solid rgba(0,0,0,0.1);
}
.output .sentence {
  font-size: 22px; 
  line-height: 1.6;
  display: inline;
  cursor: pointer;
  transition: all 0.1s;
  border: 1px solid transparent;
  padding: 4px 6px;
  text-align: left;
  color: inherit;
  font-family: inherit;
  background: transparent;
  border-radius: 6px;
  margin: 0 2px;
}
.output .sentence:hover {
  opacity: 1;
  background-color: var(--active-item-bg);
}
.output .sentence.activeSentence {
  opacity: 1;
  background-color: var(--highlight);
  border: var(--border-width) solid var(--primary);
  box-shadow: 2px 2px 0 var(--shadow-color);
}
.output .sentence time {
  margin-right: 10px;
}
.output ul {
  display: flex;
  flex-direction: column;
  gap: 12px;
}
.output ul button {
  font-size: 20px;
  display: flex;
  gap: 15px;
  text-align: left;
  padding: 16px;
  border-radius: var(--radius);
  width: 100%;
  background: var(--highlight);
  border: 1px solid var(--track);
  box-shadow: 2px 2px 0 var(--shadow-color);
  transition: all 0.1s;
}
.output ul button:hover {
  transform: translateY(-2px);
  box-shadow: 3px 3px 0 var(--shadow-color);
  border-color: var(--primary);
}
.output ul button.activeItem {
  background: var(--active-item-bg);
  border: 2px solid var(--primary);
  box-shadow: inset 0 0 0 1px var(--primary);
}
.output ul button p {
  font-size: 20px;
}

.output .apiError {
  color: #FFF;
  background-color: #EF5350;
  padding: 20px;
  border-radius: var(--radius);
  border: var(--border-width) solid #C62828;
  box-shadow: 4px 4px 0 rgba(198, 40, 40, 0.4);
  font-family: var(--font-body);
  font-size: 18px;
  display: flex;
  align-items: center;
  gap: 10px;
}

.output .textResponse {
  white-space: pre-wrap;
  line-height: 1.6;
  font-size: 20px;
}

.modeEmojis .sentence {
  font-size: 40px;
  margin-right: 20px;
}
.modeEmojis .sentence time {
  top: -8px;
}

.modeHaiku .sentence {
  display: block;
  font-size: 24px;
  margin-bottom: 15px;
  border-left: 4px solid var(--accent);
  padding-left: 15px;
  background: var(--highlight);
  padding: 15px;
  border-radius: var(--radius);
  box-shadow: 2px 2px 0 var(--shadow-color);
}

.modeTable table {
  width: 100%;
  border-collapse: separate;
  border-spacing: 0;
  border: var(--border-width) solid var(--border);
  border-radius: var(--radius);
  overflow: hidden;
  box-shadow: 3px 3px 0 var(--shadow-color);
  background: var(--highlight);
}
.modeTable th {
  text-align: left;
  background: var(--background);
  color: var(--text);
  font-family: var(--font-header);
  font-size: 12px;
  padding: 15px;
  border-bottom: var(--border-width) solid var(--border);
  border-right: 1px solid var(--track);
}
.modeTable th:last-child {
    border-right: none;
}
.modeTable td {
  padding: 15px;
  border-bottom: 1px solid var(--track);
  border-right: 1px solid var(--track);
}
.modeTable td:last-child {
    border-right: none;
}
.modeTable tr:last-child td {
    border-bottom: none;
}
.modeTable tr.activeRow td {
  background-color: var(--active-item-bg);
}

.loading {
  display: flex;
  align-items: center;
  gap: 20px;
  font-family: var(--font-body);
  font-size: 20px;
  padding: 30px;
  background: var(--highlight);
  border: var(--border-width) solid var(--border);
  border-radius: var(--radius);
  box-shadow: 4px 4px 0 var(--shadow-color);
  justify-content: center;
}

/* Spinner - Less glitchy, more smooth retro */
.spinner {
  width: 24px;
  height: 24px;
  border: 4px solid var(--track);
  border-top-color: var(--primary);
  border-radius: 50%;
  animation: spin 1s linear infinite;
}
@keyframes spin {
  to { transform: rotate(360deg); }
}

.cancelButton {
  border: var(--border-width) solid var(--border);
  padding: 6px 12px;
  border-radius: var(--radius);
  background: var(--surface);
  color: var(--text);
  font-size: 16px;
}
.cancelButton:hover {
    background: var(--background);
}

.lineChart {
  width: 100%;
  height: 100%;
  min-height: 300px;
  border: var(--border-width) solid var(--border);
  background: var(--highlight);
  box-shadow: 4px 4px 0 var(--shadow-color);
  border-radius: var(--radius);
  padding: 10px;
}
.lineChart path {
  fill: none;
  stroke: var(--primary);
  stroke-width: 3px; 
  stroke-linecap: round; 
  stroke-linejoin: round;
}
.lineChart circle {
  fill: var(--surface);
  stroke: var(--secondary);
  stroke-width: 2px;
}

.axisLabels text {
  text-anchor: middle;
  font-size: 16px;
  fill: var(--text);
  font-family: var(--font-body);
}

.axisTitle {
  font-size: 14px;
  fill: var(--text);
  font-family: var(--font-header);
}

.dataPoint text {
  fill: var(--text);
  font-size: 14px;
  text-anchor: middle;
  font-family: var(--font-body);
}

.timeLabels text {
  cursor: pointer;
  fill: var(--link);
  text-decoration: none;
  font-weight: bold;
}
.timeLabels text:hover {
    fill: var(--secondary);
    text-decoration: underline;
}

video {
  width: 100%;
  height: 100%;
  max-height: calc(50vh - 54px);
  margin: 0 auto;
}

.videoPlayer {
  flex: 1;
  background: #111;
  display: flex;
  align-items: stretch;
  flex-direction: column;
  justify-content: center;
  font-size: 0;
  position: relative;
  user-select: none;
  border-left: var(--border-width) solid var(--border);

  /* Modern Monitor Look - Cleaner than CRT */
  border: 4px solid #222;
  border-radius: 8px;
  box-shadow: 0 4px 10px rgba(0,0,0,0.3);
}

.videoPlayer:fullscreen {
  max-height: 100vh;
  border: none;
  border-radius: 0;
}


.videoPlayer:has(.timecodeMarker:hover) .videoCaption {
  opacity: 0;
}
.mediaContainer {
  display: flex;
  flex: 1;
  position: relative;
  min-height: 200px;
  overflow: hidden;
  border-radius: 4px 4px 0 0;
}

.audioPlaceholder {
  position: absolute;
  inset: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  z-index: 1;
  pointer-events: none;
  background: radial-gradient(circle, #333 0%, #111 100%);
}
.audioPlaceholder .icon {
    font-size: 80px;
    color: var(--primary);
    opacity: 0.5;
}

.emptyVideo {
  min-height: 50vh;
  color: #fff;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  font-size: 20px;
  width: 100%;
  font-family: var(--font-body);
}
.uploadLabel {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 20px;
  cursor: pointer;
  width: 100%;
  height: 100%;
  padding: 20px;
}
.emptyVideo .icon {
  font-size: 64px;
  color: var(--secondary);
  margin-bottom: 10px;
}

.emptyVideo p {
  max-width: 500px;
  text-align: center;
  line-height: 1.5;
}
.emptyVideo p.error {
    color: #FFF;
    background-color: #EF5350;
    padding: 15px 25px;
    border-radius: var(--radius);
    box-shadow: 0 4px 8px rgba(0,0,0,0.2);
}

.uploadProgress {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 15px;
  width: 100%;
  max-width: 300px;
  color: #fff;
  cursor: default;
  padding: 30px;
  border: var(--border-width) solid var(--border);
  background: var(--surface);
  color: var(--text);
  border-radius: var(--radius);
  box-shadow: 4px 4px 0 var(--shadow-color);
}

.progressBar {
  width: 100%;
  height: 12px;
  background-color: var(--track);
  border-radius: 6px;
  overflow: hidden;
}

.progressFill {
  width: 0%;
  height: 100%;
  background-color: var(--accent);
  transition: width 0.3s ease;
  border-radius: 6px;
}

.videoCaption {
  background: rgba(0, 0, 0, 0.7);
  backdrop-filter: blur(4px);
  position: absolute;
  bottom: 80px;
  text-align: center;
  padding: 12px 20px;
  color: #FFF;
  max-width: 720px;
  font-size: 22px;
  margin-inline: 30px;
  left: 50%;
  translate: -50% 0;
  width: -webkit-fill-available;
  border-radius: 8px;
  transition: opacity 0.2s;
  z-index: 2;
  font-family: var(--font-body);
  text-shadow: 1px 1px 0 #000;
  border: 1px solid rgba(255,255,255,0.2);
}

.videoControls {
  font-size: 12px;
  position: relative;
  background: #222; /* Darker controls */
  z-index: 3;
  color: #FFF;
  border-radius: 0 0 4px 4px;
}

/* Modern Retro Scrubber */
.videoScrubber {
  height: 12px; 
  transform-origin: bottom;
  transition: none;
  overflow: hidden;
  background: #333;
  cursor: pointer;
}
.videoScrubber:hover {
    height: 16px;
}
.videoScrubber input {
  position: relative;
  top: -6px;
  height: 20px;
  appearance: none;
  width: 100%;
  background: transparent;
  border: none;
  box-shadow: none;
  border-radius: 0;
}
/* Custom range track for retro look */
.videoScrubber input::-webkit-slider-runnable-track {
    background: linear-gradient(to right, var(--primary) 0%, var(--primary) var(--pct), #555 var(--pct), #555 100%);
    height: 100%;
}
.videoScrubber input::-webkit-slider-thumb {
  opacity: 0;
}

.videoTime {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 12px 20px;
  font-size: 16px;
  border-top: 1px solid #333;
  gap: 20px;
  background: #222;
  font-family: var(--font-header);
}
.videoTime button {
  background: transparent;
  border: none;
  box-shadow: none;
  color: #AAA;
  padding: 0;
  transition: color 0.1s;
}
.videoTime button:hover {
    color: #FFF;
    transform: none;
    background: transparent;
}
.videoTime .timeDisplay {
  flex-shrink: 0;
  font-family: var(--font-body);
  font-size: 20px;
  color: #DDD;
}

.volumeControls {
    display: flex;
    align-items: center;
    gap: 15px;
    flex: 1;
}

.volumeSlider {
    width: 100%;
    max-width: 120px;
    height: 6px;
    accent-color: var(--primary);
    background: #444;
    border: none;
    box-shadow: none;
    border-radius: 3px;
}


.timecodeList {
  overflow: auto;
  padding: 10px 20px;
}
.timecodeList td {
  padding: 10px 5px;
}
.timecodeList button {
  color: var(--link);
  box-shadow: none;
  border: none;
  background: transparent;
}
.timecodeList button:hover {
  color: var(--secondary);
  text-decoration: underline;
}

.timecodeMarkers {
  position: absolute;
  inset: 0;
  pointer-events: none;
}

.timecodeMarker {
  position: absolute;
  top: 0;
  width: 2px;
  background: rgba(255, 255, 255, 0.5); 
  translate: -1px 0;
  z-index: 4;
}
.timecodeMarker:hover {
    width: 4px;
    background: var(--accent);
    translate: -2px 0;
    z-index: 5;
}
.timecodeMarker:hover .timecodeMarkerLabel {
  opacity: 1;
}

.timecodeMarkerTick {
  height: 12px;
  pointer-events: auto;
  cursor: pointer;
  background: transparent;
}

.timecodeMarkerLabel {
  background: #222;
  border: 1px solid #555;
  box-shadow: 0 4px 8px rgba(0,0,0,0.5);
  opacity: 0;
  display: flex;
  flex-direction: column;
  gap: 4px;
  font-size: 14px;
  transition: opacity 0.1s;
  pointer-events: none;
  position: absolute;
  top: 0;
  translate: 0 calc(-100% - 20px);
  z-index: 99;
  padding: 8px 12px;
  border-radius: 6px;
  width: max-content;
  max-width: 240px;
  color: #EEE;
  font-family: var(--font-body);
}
.timecodeMarkerLabel.right {
  right: 0;
}
.timecodeMarkerLabel p {
  color: var(--accent);
  font-size: 16px;
}

.actionToolbar {
  display: flex;
  gap: 15px;
  padding-bottom: 20px;
  border-bottom: 2px solid var(--track);
  flex-wrap: wrap;
  background: var(--surface);
  margin-bottom: 10px;
}

.actionButton {
  background-color: var(--surface);
  border: var(--border-width) solid var(--border);
  padding: 8px 16px;
  border-radius: var(--radius);
  transition: all 0.1s;
  font-family: var(--font-header);
  font-size: 11px;
  box-shadow: 2px 2px 0 var(--shadow-color);
}

.actionButton:hover {
  background-color: var(--highlight);
  transform: translateY(-1px);
  box-shadow: 3px 3px 0 var(--shadow-color);
}

.copyButtonContainer {
  position: relative;
  display: flex;
  box-shadow: 2px 2px 0 var(--shadow-color);
  border-radius: var(--radius);
}

.copyButton {
  background-color: var(--surface);
  border: var(--border-width) solid var(--border);
  padding: 8px 16px;
  border-radius: var(--radius) 0 0 var(--radius);
  transition: none;
  box-shadow: none; 
  margin: 0;
  font-family: var(--font-header);
  font-size: 11px;
}

.copyButton.copied {
  background-color: var(--accent);
  color: #000;
}
.dark .copyButton.copied {
  background-color: var(--accent);
}

.copyDropdownButton {
  background-color: var(--surface);
  border: var(--border-width) solid var(--border);
  border-left: none;
  padding: 8px;
  border-radius: 0 var(--radius) var(--radius) 0;
  transition: none;
  box-shadow: none;
  margin: 0;
}

.copyButton:hover,
.copyDropdownButton:hover {
  background-color: var(--highlight);
}

.copyDropdown {
  position: absolute;
  top: 100%;
  right: 0;
  margin-top: 6px;
  background-color: var(--surface);
  border: var(--border-width) solid var(--border);
  border-radius: var(--radius);
  box-shadow: 4px 4px 0 var(--shadow-color);
  z-index: 10;
  overflow: hidden;
  display: flex;
  flex-direction: column;
}

.copyDropdown button {
  padding: 12px 16px;
  text-align: left;
  width: 100%;
  white-space: nowrap;
  border: none;
  border-bottom: 1px solid var(--track);
  box-shadow: none;
  font-family: var(--font-body);
  font-size: 18px;
  border-radius: 0;
}
.copyDropdown button:last-child {
    border-bottom: none;
}

.copyDropdown button:hover {
  background-color: var(--active-item-bg);
}


/* Responsive Styles */
@media (max-width: 800px) {
  main {
    height: auto;
    overflow: auto;
  }
  .contentWrapper {
    height: auto;
    overflow: visible;
    border: none;
  }
  .top {
    flex-direction: column;
    height: auto; 
    min-height: 0;
    border-bottom: var(--border-width) solid var(--border);
  }
  .modeSelector {
    width: 100% !important; 
    border-right: none;
    border-bottom: var(--border-width) solid var(--border);
  }
  .resizer {
    display: none; 
  }
  .modeSelector.hide + .collapseButton {
    display: none;
  }
  .collapseButton {
    display: none;
  }
  .videoPlayer {
    border-left: none;
    min-height: 300px;
    border: none;
    border-radius: 0;
    box-shadow: none;
    border-bottom: var(--border-width) solid var(--border);
  }
  video {
    max-height: 60vh;
  }
  .emptyVideo {
    min-height: 300px;
  }
  .output {
    min-height: 300px;
  }
}

/* User Profile & Login Styles */
.userProfile {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding-bottom: 15px;
  margin-bottom: 15px;
  border-bottom: var(--border-width) solid var(--border);
}
.userName {
  font-family: var(--font-header);
  font-size: 12px;
  color: var(--primary);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
  max-width: 150px;
}
.logoutButton {
  padding: 4px;
  background: transparent;
  border: none;
  box-shadow: none;
  color: var(--mid);
}
.logoutButton:hover {
  color: var(--secondary);
  background: transparent;
  transform: none;
  box-shadow: none;
}
.logoutButton .icon {
  font-size: 20px;
}

/* Modal */
.modalOverlay {
  position: fixed;
  inset: 0;
  background: rgba(0,0,0,0.7);
  backdrop-filter: blur(2px);
  z-index: 1000;
  display: flex;
  align-items: center;
  justify-content: center;
}

.modalContent {
  background: var(--surface);
  border: var(--border-width) solid var(--border);
  padding: 30px;
  border-radius: var(--radius);
  box-shadow: 0 10px 25px rgba(0,0,0,0.5);
  width: 100%;
  max-width: 450px;
  display: flex;
  flex-direction: column;
  gap: 20px;
  animation: slideUp 0.2s ease-out;
}
@keyframes slideUp {
  from { transform: translateY(20px); opacity: 0; }
  to { transform: translateY(0); opacity: 1; }
}

.modalHeader {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-bottom: 10px;
}
.modalHeader h2 {
  font-size: 16px;
  color: var(--primary);
}

.closeButton {
  background: transparent;
  border: none;
  box-shadow: none;
  color: var(--text);
  padding: 5px;
}
.closeButton:hover {
  background: var(--active-item-bg);
  transform: none;
  box-shadow: none;
}

.modalActions {
  display: flex;
  justify-content: flex-end;
  gap: 15px;
  margin-top: 10px;
}

/* Settings Button */
.settingsButton {
  position: absolute;
  top: 15px;
  right: 15px;
  z-index: 20;
  background: rgba(0,0,0,0.5);
  color: #FFF;
  border: 1px solid rgba(255,255,255,0.2);
  padding: 8px;
  border-radius: var(--radius);
  transition: all 0.2s;
}
.settingsButton:hover {
  background: rgba(0,0,0,0.8);
  transform: rotate(90deg);
}


/* Login Page Specific Overrides for High Contrast / Retro Look */
.loginPage {
  background-color: #e0e0e0;
  background-image: none; /* Remove grid for the clean look in screenshot */
  font-family: var(--font-body);
}

.loginCard {
  background: #ffffff;
  border: 4px solid #000000; /* Thicker, bolder border */
  border-radius: 0; /* Boxy retro look */
  box-shadow: 10px 10px 0px rgba(0,0,0,0.2); /* Hard shadow */
  color: #000000;
  max-width: 550px;
}

.loginHeader {
  color: #000000;
  margin-bottom: 30px;
}
.loginHeader .icon {
  font-size: 40px;
  margin-right: 15px;
}
.loginHeader h1 {
  font-size: 28px;
  color: #000000;
}

.loginDescription {
  color: #444444; /* Dark gray for readability */
  font-size: 18px;
  margin-bottom: 30px;
}

.inputGroup label {
  color: #000000;
  font-family: var(--font-header);
  font-size: 14px;
  margin-bottom: 8px;
  display: block;
  text-transform: uppercase;
}

.inputGroup input {
  background: #ffffff;
  border: 2px solid #000000;
  color: #000000;
  border-radius: 0;
  box-shadow: none;
  padding: 15px;
  font-size: 18px;
}
.inputGroup input:focus {
  border-color: #000000;
  background: #f0f0f0;
  box-shadow: 4px 4px 0 rgba(0,0,0,0.1);
}
.inputGroup input::placeholder {
  color: #888888;
  opacity: 1;
}

.helper {
  color: #666666;
  font-size: 14px;
}
.helper a {
  color: #000000;
  text-decoration: underline;
  font-weight: bold;
}

.loginButton {
  background: #000000;
  color: #ffffff;
  border: 2px solid #000000;
  font-family: var(--font-header);
  font-size: 16px;
  text-transform: uppercase;
  padding: 18px;
  margin-top: 20px;
  transition: all 0.2s;
  box-shadow: 5px 5px 0 rgba(0,0,0,0.2);
}
.loginButton:hover {
  background: #333333;
  color: #ffffff;
  transform: translate(-2px, -2px);
  box-shadow: 7px 7px 0 rgba(0,0,0,0.2);
}
.loginButton:active {
  transform: translate(0, 0);
  box-shadow: none;
}
.loginButton .icon {
  color: #ffffff;
}
